pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
        // Set up a jojoTeam that the test can control
        address team = makeAddr("jojoTeam");
        // Use vm.store to set the private jojoTeam variable
        // Slot 0 is empty, slot 1 is jojoTeam (address)
        bytes32 teamSlot = bytes32(uint256(1));
        vm.store(address(c), teamSlot, bytes32(uint256(uint160(team))));
        // Give the team some ETH to deploy
        vm.deal(team, 100 ether);
    }

    function testFuzz_property(string calldata description) public {
        // Restrict description to admissible values (non-empty, reasonable length)
        vm.assume(bytes(description).length > 0 && bytes(description).length <= 100);

        // The jojoTeam is fixed as the address we set up; prank as them.
        address team = makeAddr("jojoTeam");
        vm.prank(team);

        // Call newEmergencyOracle and get the returned oracle address
        // We can't directly capture the return value from the transaction, so we'll read the event.
        // Instead, we'll use try/catch with a low-level call to get the return data, but
        // newEmergencyOracle is a non-view external function that returns nothing.
        // The property is about the owner of the deployed contract. We can find the deployed
        // address by reading the event emitted by C.

        // Since C emits NewEmergencyOracle, we can capture the address from the log.
        // We record the call and then inspect the logs.
        vm.recordLogs();
        c.newEmergencyOracle(description);
        Vm.Log[] memory logs = vm.getRecordedLogs();

        // Find the NewEmergencyOracle event from C
        // Event signature: NewEmergencyOracle(address,address)
        bool found = false;
        address newOracleAddr;
        for (uint256 i = 0; i < logs.length; i++) {
            if (logs[i].emitter == address(c)) {
                // Check topic0 matches the event signature
                bytes32 eventSig = keccak256("NewEmergencyOracle(address,address)");
                if (logs[i].topics[0] == eventSig) {
                    // The second indexed parameter (address newOracle) is topics[2]
                    newOracleAddr = address(uint160(uint256(logs[i].topics[2])));
                    found = true;
                    break;
                }
            }
        }
        require(found, "Event not found");

        // Check the owner of the newly deployed EmergencyOracle
        // EmergencyOracle has a public owner() view function
        (bool ok, bytes memory data) = newOracleAddr.call(abi.encodeWithSignature("owner()"));
        require(ok, "owner() call failed");
        address oracleOwner = abi.decode(data, (address));

        // The property: the owner must be the jojoTeam (team), not address(0)
        assertTrue(oracleOwner == team);
    }
}

