pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address jojoTeam, string calldata description) public {
        vm.assume(jojoTeam != address(0));
        // make the jojoTeam the authorized caller
        vm.store(address(c), bytes32(uint256(0)), bytes32(uint256(uint160(jojoTeam))));
        vm.prank(jojoTeam);
        try c.newEmergencyOracle(description) {
            assertTrue(isOwnerNewEmergencyOracle(jojoTeam));
        } catch {
            assertTrue(false, "newEmergencyOracle should not revert");
        }
    }
    function isOwnerNewEmergencyOracle(address expectedOwner) internal returns (bool) {
        // read the last emitted NewEmergencyOracle event to get the deployed oracle address
        // we do this by examining the logs directly using Foundry's recorded logs
        Vm.Log[] memory entries = vm.getRecordedLogs();
        for (uint256 i = entries.length; i > 0; i--) {
            // NewEmergencyOracle(address owner, address newOracle)
            // topic0: keccak256("NewEmergencyOracle(address,address)")
            if (entries[i-1].topics[0] == keccak256("NewEmergencyOracle(address,address)")) {
                address newOracle = address(uint160(uint256(entries[i-1].topics[2])));
                // we can get the owner by calling the emergency oracle contract's owner()
                (bool ok, bytes memory ret) = newOracle.staticcall(abi.encodeWithSignature("owner()"));
                require(ok, "owner() call failed");
                address actualOwner = abi.decode(ret, (address));
                return actualOwner == expectedOwner;
            }
        }
        revert("No NewEmergencyOracle log found");
    }
}

